using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Reflection;
using System.Text;

public enum AdhkarSet { Morning, Evening, AfterPrayer, Sleep }

public class Dhikr
{
    public int Id, Repeat;
    public string Text;
}

// The text lives in data\adhkar.tsv (generated by tools\build-adhkar-data.ps1) and is embedded in the exe.
// It is only read when a reader window opens, so it costs no memory while idle.
public static class Adhkar
{
    public static string TitleKey(AdhkarSet set)
    {
        return set == AdhkarSet.Morning ? "adhkarM" : set == AdhkarSet.Evening ? "adhkarE" : set == AdhkarSet.AfterPrayer ? "adhkarA" : "adhkarS";
    }

    // The set that fits the time of day. day holds that day's times; a missing time falls back to the clock.
    public static AdhkarSet Suggest(DateTime now, DateTime[] day)
    {
        DateTime fajr = day[0] == DateTime.MinValue ? now.Date.AddHours(5) : day[0];
        DateTime asr = day[3] == DateTime.MinValue ? now.Date.AddHours(15) : day[3];
        DateTime isha = day[5] == DateTime.MinValue ? now.Date.AddHours(20) : day[5];
        if (now >= isha || now < fajr) return AdhkarSet.Sleep;
        return now >= asr ? AdhkarSet.Evening : AdhkarSet.Morning;
    }

    public static List<Dhikr> Load(AdhkarSet set)
    {
        string letter = set == AdhkarSet.Morning ? "M" : set == AdhkarSet.Evening ? "E" : set == AdhkarSet.AfterPrayer ? "A" : "S";
        var list = new List<Dhikr>();
        using (Stream s = Assembly.GetExecutingAssembly().GetManifestResourceStream("adhkar.tsv"))
        {
            if (s == null) return list;
            using (var r = new StreamReader(s, Encoding.UTF8))
            {
                string line;
                while ((line = r.ReadLine()) != null)
                {
                    string[] f = line.Split('\t');
                    if (f.Length != 4 || f[0].IndexOf(letter, StringComparison.Ordinal) < 0) continue;
                    list.Add(new Dhikr
                    {
                        Id = int.Parse(f[1], CultureInfo.InvariantCulture),
                        Repeat = int.Parse(f[2], CultureInfo.InvariantCulture),
                        Text = f[3],
                    });
                }
            }
        }
        return list;
    }
}
